// Ждем клика по кнопке
document.getElementById('load-data-btn').addEventListener('click', async () => {
    const loader = document.getElementById('loader');
    const card = document.getElementById('card-container');
    
    loader.style.display = 'block'; // Показываем лоадер
    card.style.display = 'none';    // Прячем прошлую карточку

    try {
        // В реальной жизни тут будет: const response = await fetch('https://api.example.com/product/1');
        // const data = await response.json();
        const data = await mockFetch(); 

        // Передаем полученный JSON в функцию отрисовки
        renderData(data);

    } catch (error) {
        alert('Ошибка при получении данных');
        console.error(error);
    } finally {
        loader.style.display = 'none'; // Выключаем лоадер
    }
});

// Функция, которая берет JSON и красиво подставляет данные в HTML
function renderData(product) {
    const card = document.getElementById('card-container');
    const imgElement = document.getElementById('product-image');
    const titleElement = document.getElementById('product-title');
    const priceElement = document.getElementById('product-price');

    // Чистая строка из твоего API/загрузчика
    let base64String = product.imageBase64;

    // ПРОВЕРКА: Если строка НЕ начинается с "data:", добавляем префикс сами
    if (!base64String.startsWith('data:')) {
        base64String = `data:image/png;base64,${base64String}`;
    }

    // Теперь вставляем готовую строку
    imgElement.src = base64String;
    
    titleElement.textContent = product.title;
    priceElement.textContent = `${product.price} руб.`;

    card.style.display = 'block';
}


/* =====================================================================
   ИМИТАЦИЯ СЕРВЕРА (заменяет реальный fetch для теста в браузере)
   ===================================================================== */
function mockFetch() {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve({
                id: 101,
                title: "Беспроводные наушники",
                price: 4500,
                // Реальный Base64 код маленького синего квадрата (2x2 пикселя).
                // Сервер пришлет подобную длинную строку.
                imageBase64: "data:image/jpeg;base64,"
            });
        }, 1000); // Имитируем задержку сети в 1 секунду
    });
}